private fun destroyNodeEffects(node: PathlandNode) {
    nodeBindings.remove(node.id)?.let { effects ->
        for (effect in effects) {
            effect.destroy()
            bindings.remove(effect)
        }
    }
    forgetInputsForNode(node)
}

private fun applyController(node: PathlandNode, c: MediaController) {
    node.properties[Properties.MEDIA_SOURCE] = c.sourceSignal().get()
    node.propertyBindings[Properties.MEDIA_SOURCE] = c.sourceSignal()
    node.properties[Properties.PLAYBACK_STATE] = if (c.playing().get()) 1 else 0
    node.propertyBindings[Properties.PLAYBACK_STATE] = c.playing()
    node.properties[Properties.MEDIA_POSITION] = c.position().get()
    node.propertyBindings[Properties.MEDIA_POSITION] = c.position()
    node.properties[Properties.MEDIA_VOLUME] = c.volume().get()
    node.propertyBindings[Properties.MEDIA_VOLUME] = c.volume()
    node.properties[Properties.MEDIA_MUTED] = if (c.muted().get()) 1 else 0
    node.propertyBindings[Properties.MEDIA_MUTED] = c.muted()
    node.properties[Properties.MEDIA_LOOP] = if (c.loop().get()) 1 else 0
    node.propertyBindings[Properties.MEDIA_LOOP] = c.loop()
    node.properties[Properties.MEDIA_RATE] = c.rate().get()
    node.propertyBindings[Properties.MEDIA_RATE] = c.rate()
    node.mediaInput = object : MediaInput {
        override fun onPlayStateChanged(playing: Boolean) = c.playingReport().set(playing)
        override fun onTimeUpdated(seconds: Float) = c.time().set(seconds)
        override fun onDurationChanged(seconds: Float) = c.duration().set(seconds)
        override fun onEnded() = c.onEnded().run()
        override fun onVolumeChanged(volume: Float) = c.volumeReport().set(volume)
    }
}

private fun emitNode(node: PathlandNode) {
    emitNode(node, null, -1)
}

private fun emitNode(node: PathlandNode, parentId: Int?, index: Int) {
    sink.createNode(node.id, node.component)
    if (parentId != null) sink.insertChild(parentId, node.id, index)
    ensureBindingId(node)
    for ((property, value) in node.properties) emitProperty(node.id, property, value)
    val text = node.textValue()
    if (text != null && text.isNotEmpty()) sink.setText(node.id, text)
    if (node.dateBinding != null) sink.setDate(node.id, node.days, node.millisOfDay)
    var childIndex = 0
    for (child in node.children) emitNode(child, node.id, childIndex++)
}

private fun ringSink(): Boolean = sink.requiresBindingId()

private fun ensureBindingId(node: PathlandNode) {
    if (ringSink() && (node.textInput != null || node.valueInput != null || node.dateInput != null)) {
        node.properties.computeIfAbsent(Properties.BINDING_ID) { node.id }
    }
}

private fun emitProperty(nodeId: Int, property: Int, value: Any?) {
    val token = value as? TokenPath
    val valueType = if (token?.tokenPath() != null) ValueTypes.DESIGN_TOKEN
    else ValueTypes.forProperty(property)
    sink.setProperty(nodeId, property, valueType, value!!)
}

private fun propertyValuesEqual(a: Any?, b: Any?): Boolean {
    if (a is FloatArray && b is FloatArray) return a.contentEquals(b)
    return Objects.equals(a, b)
}

private fun isConstant(signal: Signal<*>): Boolean = signal is ConstantSignal<*>

private fun trackBinding(slot: ViewSlot, nodeId: Int, effect: EffectRef) {
    slot.bindings.add(effect)
    bindings.add(effect)
    nodeBindings.computeIfAbsent(nodeId) { ArrayList() }.add(effect)
}

private fun registerNodeBindings(slot: ViewSlot, node: PathlandNode) {
    node.textBinding?.let { textBinding ->
        if (!isConstant(textBinding)) {
            val effect = Signals.effect {
                val value = textBinding.get()
                if (value != node.text) {
                    node.text = value
                    sink.beginFrame()
                    sink.setText(node.id, value)
                    sink.endFrame()
                }
            }
            trackBinding(slot, node.id, effect)
        }
    }
    node.dateBinding?.let { dateBinding ->
        if (!isConstant(dateBinding)) {
            val effect = Signals.effect {
                val days = dateBinding.get()
                if (days != node.days) {
                    node.days = days
                    sink.beginFrame()
                    sink.setDate(node.id, days, node.millisOfDay)
                    sink.endFrame()
                }
            }
            trackBinding(slot, node.id, effect)
        }
    }
    for ((property, signal) in node.propertyBindings) {
        if (isConstant(signal)) continue
        val effect = Signals.effect {
            val value = ReactiveValues.from(property, signal)
            if (value != node.properties[property]) {
                node.properties[property] = value
                sink.beginFrame()
                emitProperty(node.id, property, value)
                sink.endFrame()
            }
        }
        trackBinding(slot, node.id, effect)
    }
    val activePath = node.activePath
    if (activePath != null && node.pathChangeListeners.isNotEmpty()) {
        val listeners = node.pathChangeListeners.toList()
        val effect = Signals.effect({
            val path = activePath.get()
            for (listener in listeners) listener.accept(path)
        }, EffectOptions.allowWrites())
        trackBinding(slot, node.id, effect)
    }
}

private fun reconcileChildren(
    parent: PathlandNode,
    oldList: List<PathlandNode>,
    newList: List<PathlandNode>,
    ops: MutableList<Runnable>,
) {
    val n = maxOf(oldList.size, newList.size)
    for (i in 0 until n) {
        val old = if (i < oldList.size) oldList[i] else null
        val fresh = if (i < newList.size) newList[i] else null
        if (old != null && fresh != null && old.component == fresh.component) {
            fresh.id = old.id
            reconcileNode(old, fresh, ops)
        } else {
            if (old != null) {
                val parentId = parent.id
                val oldId = old.id
                ops.add(Runnable {
                    sink.removeChild(parentId, oldId)
                    sink.deleteNode(oldId)
                })
            }
            if (fresh != null) {
                if (fresh.id == 0) fresh.id = freshIdFor(fresh)
                emitSubtreeInto(ops, fresh, parent.id, i)
            }
        }
    }
}

private fun reconcileNode(old: PathlandNode, fresh: PathlandNode, ops: MutableList<Runnable>) {
    ensureBindingId(fresh)
    for ((property, value) in fresh.properties) {
        if (!propertyValuesEqual(value, old.properties[property])) {
            val id = fresh.id
            ops.add(Runnable { emitProperty(id, property, value) })
        }
    }
    val oldText = old.text
    val freshText = currentText(fresh)
    if (oldText != freshText) {
        val id = fresh.id
        ops.add(Runnable { sink.setText(id, freshText!!) })
    }
    if (old.days != fresh.days || old.millisOfDay != fresh.millisOfDay) {
        val id = fresh.id
        val days = fresh.days
        val millis = fresh.millisOfDay
        ops.add(Runnable { sink.setDate(id, days, millis) })
    }
    reconcileChildren(fresh, old.children, fresh.children, ops)
}

private fun emitSubtreeInto(ops: MutableList<Runnable>, node: PathlandNode, parentId: Int, index: Int) {
    ensureBindingId(node)
    val id = node.id
    val component = node.component
    ops.add(Runnable { sink.createNode(id, component) })
    ops.add(Runnable { sink.insertChild(parentId, id, index) })
    for ((property, value) in node.properties) {
        ops.add(Runnable { emitProperty(id, property, value) })
    }
    val text = currentText(node)
    if (text != null && text.isNotEmpty()) {
        ops.add(Runnable { sink.setText(id, text) })
    }
    if (node.dateBinding != null) {
        val days = node.days
        val millis = node.millisOfDay
        ops.add(Runnable { sink.setDate(id, days, millis) })
    }
    var childIndex = 0
    for (child in node.children) {
        child.id = freshIdFor(child)
        emitSubtreeInto(ops, child, id, childIndex++)
    }
}

private fun currentText(node: PathlandNode): String? =
    node.textBinding?.let { Signals.untracked { it.get() } } ?: node.text

companion object {
    private val CURRENT = ThreadLocal<Emitter>()

    /** The emitter driving the current render on this thread, or null. */
    fun current(): Emitter? = CURRENT.get()

    /** The ids that occur more than once in [root]'s subtree, in pre-order. */
    fun duplicateIds(root: PathlandNode): List<Int> {
        val seen = LinkedHashSet<Int>()
        val duplicates = LinkedHashSet<Int>()
        collectDuplicateIds(root, seen, duplicates)
        return ArrayList(duplicates)
    }

    private fun collectDuplicateIds(
        node: PathlandNode,
        seen: MutableSet<Int>,
        duplicates: MutableSet<Int>,
    ) {
        if (!seen.add(node.id)) duplicates.add(node.id)
        for (child in node.children) collectDuplicateIds(child, seen, duplicates)
    }
}

package dev.pathland.view.core.transport

/**
 * The emission target for opcodes: a self-contained frame sink (SSR/WebSocket) or
 * the zero-copy Rust ring sink.
 */
interface OpcodeSink {
    fun beginFrame()
    fun endFrame()
    fun createNode(id: Int, component: Int)
    fun deleteNode(id: Int)
    fun insertChild(parent: Int, child: Int, index: Int)
    fun removeChild(parent: Int, child: Int)
    fun moveChild(parent: Int, child: Int, newIndex: Int)
    fun setText(nodeId: Int, text: String)
    fun setProperty(nodeId: Int, property: Int, valueType: Int, value: Any)
    fun setDate(nodeId: Int, days: Int, millisOfDay: Int)
    fun setDesignToken(path: String, valueType: Int, value: Any)

    /** Clear every application design-token override. */
    fun resetTheme() {
        throw UnsupportedOperationException("resetTheme")
    }

    /** Emit `META::SET_COLOR_SCHEME` (0 platform, 1 light, 2 dark). */
    fun setColorScheme(mode: Int) {
        throw UnsupportedOperationException("setColorScheme")
    }

    /** Emit `META::SET_WINDOW_METADATA`; an empty string clears the field. */
    fun setWindowMetadata(field: Int, value: String) {
        throw UnsupportedOperationException("setWindowMetadata")
    }

    /** Whether this sink feeds a renderer that gates raw inputs on a `BINDING_ID`. */
    fun requiresBindingId(): Boolean = false
}

package dev.pathland.view.core.transport

import dev.pathland.view.core.protocol.Categories
import dev.pathland.view.core.protocol.Commands
import dev.pathland.view.core.protocol.Opcode
import dev.pathland.view.core.protocol.TokenPath
import dev.pathland.view.core.protocol.ValueEncoder
import dev.pathland.view.core.protocol.ValueTypes
import java.io.ByteArrayOutputStream
import java.nio.charset.StandardCharsets

/** An [OpcodeSink] that accumulates a self-contained [ProtocolFrame]. */
open class FrameOpcodeSink : OpcodeSink {
    private val opcodes = ArrayList<Opcode>()
    private val strings = ByteArrayOutputStream()
    private var frame: ProtocolFrame = ProtocolFrame.EMPTY
    private var framesProduced = 0

    fun frame(): ProtocolFrame = frame
    fun framesProduced(): Int = framesProduced
    fun hasChanges(): Boolean = opcodes.isNotEmpty()

    override fun beginFrame() {
        opcodes.clear()
        strings.reset()
    }

    override fun endFrame() {
        frame = ProtocolFrame(opcodes.toList(), strings.toByteArray())
        framesProduced++
    }

    override fun createNode(id: Int, component: Int) {
        push(Categories.TREE, Commands.Tree.CREATE_NODE, 0, id, component, 0)
    }

    override fun deleteNode(id: Int) {
        push(Categories.TREE, Commands.Tree.DELETE_NODE, 0, id, 0, 0)
    }

    override fun insertChild(parent: Int, child: Int, index: Int) {
        push(Categories.TREE, Commands.Tree.INSERT_CHILD, 0, parent, child, index)
    }

    override fun removeChild(parent: Int, child: Int) {
        push(Categories.TREE, Commands.Tree.REMOVE_CHILD, 0, parent, child, 0)
    }

    override fun moveChild(parent: Int, child: Int, newIndex: Int) {
        push(Categories.TREE, Commands.Tree.MOVE_CHILD, 0, parent, child, newIndex)
    }

    override fun setText(nodeId: Int, text: String) {
        val offset = strings.size()
        writeString(text)
        push(Categories.PARAMETER, Commands.Parameter.SET_TEXT, 0, nodeId, offset, 0)
    }

    override fun setProperty(nodeId: Int, property: Int, valueType: Int, value: Any) {
        val b = (valueType shl 16) or (property and 0xFFFF)
        when (valueType) {
            ValueTypes.STRING -> {
                val offset = strings.size()
                writeString(value as String)
                push(Categories.PARAMETER, Commands.Parameter.SET_PROPERTY, 0, nodeId, b, offset)
            }
            ValueTypes.DESIGN_TOKEN -> {
                val offset = strings.size()
                writeString((value as TokenPath).tokenPath() ?: "")
                push(Categories.PARAMETER, Commands.Parameter.SET_PROPERTY, 0, nodeId, b, offset)
            }
            ValueTypes.LIST -> {
                val offset = strings.size()
                val elements = value as FloatArray
                writeIntLE(elements.size)
                for (element in elements) {
                    val bits = element.toRawBits()
                    strings.write(bits and 0xFF)
                    strings.write((bits ushr 8) and 0xFF)
                    strings.write((bits ushr 16) and 0xFF)
                    strings.write((bits ushr 24) and 0xFF)
                }
                push(Categories.PARAMETER, Commands.Parameter.SET_PROPERTY, 0, nodeId, b, offset)
            }
            else -> push(Categories.PARAMETER, Commands.Parameter.SET_PROPERTY, 0, nodeId, b,
                ValueEncoder.encodeBits(valueType, value))
        }
    }

    override fun setDate(nodeId: Int, days: Int, millisOfDay: Int) {
        push(Categories.PARAMETER, Commands.Parameter.SET_DATE, 0, nodeId, days, millisOfDay)
    }

    override fun setDesignToken(path: String, valueType: Int, value: Any) {
        val pathOffset = strings.size()
        writeString(path)
        val c = if (valueType == ValueTypes.STRING) {
            val offset = strings.size()
            writeString(value as String)
            offset
        } else {
            ValueEncoder.encodeBits(valueType, value)
        }
        push(Categories.PARAMETER, Commands.Parameter.SET_DESIGN_TOKEN, 0, pathOffset, valueType, c)
    }

    fun writeString(text: String): Int {
        val offset = strings.size()
        val utf8 = text.toByteArray(StandardCharsets.UTF_8)
        writeIntLE(utf8.size)
        strings.writeBytes(utf8)
        return offset
    }

    private fun push(category: Int, command: Int, flags: Int, a: Int, b: Int, c: Int) {
        opcodes.add(Opcode(category, command, flags, a, b, c))
    }

    private fun writeIntLE(value: Int) {
        strings.write(value and 0xFF)
        strings.write((value ushr 8) and 0xFF)
        strings.write((value ushr 16) and 0xFF)
        strings.write((value ushr 24) and 0xFF)
    }

    override fun resetTheme() {
        push(Categories.META, Commands.Meta.RESET_THEME, 0, 0, 0, 0)
    }

    override fun setColorScheme(mode: Int) {
        push(Categories.META, Commands.Meta.SET_COLOR_SCHEME, 0, mode, 0, 0)
    }

    override fun setWindowMetadata(field: Int, value: String) {
        val offset = strings.size()
        writeString(value)
        push(Categories.META, Commands.Meta.SET_WINDOW_METADATA, 0, field, offset, 0)
    }
}

package dev.pathland.view.core.transport

import dev.pathland.view.core.protocol.Categories
import dev.pathland.view.core.protocol.Commands
import dev.pathland.view.core.protocol.Opcode
import java.io.ByteArrayOutputStream
import java.nio.charset.StandardCharsets

/** The network batch codec — mirrors `pathland_core_transport`. */
object FrameCodec {
    const val MAGIC = 0x504C_504C
    const val VERSION = 1
    const val GUEST_TO_HOST = 0x0000
    const val HOST_TO_GUEST = 0x0001
    const val HEADER = 16

    /** Encode a self-contained frame as a network batch (sequence 0). */
    @JvmStatic
    fun encodeFrame(frame: ProtocolFrame): ByteArray = encodeFrame(frame, 0)

    /** Encode a self-contained frame as a guest → host batch with [sequence]. */
    @JvmStatic
    fun encodeFrame(frame: ProtocolFrame, sequence: Int): ByteArray {
        val out = ByteArrayOutputStream()
        writeHeader(out, GUEST_TO_HOST, sequence, frame.opcodes.size)
        for (op in frame.opcodes) {
            writeBytes(out, op.toBytes())
        }
        writeIntLE(out, frame.strings.size)
        writeBytes(out, frame.strings)
        return out.toByteArray()
    }

    /** Decode a self-contained frame batch into opcodes + string section. */
    @JvmStatic
    fun decodeFrame(bytes: ByteArray): ProtocolFrame {
        val parsed = parse(bytes)
        return ProtocolFrame(parsed.opcodes, parsed.strings)
    }

    /** The per-stream message sequence encoded in a batch header (offset 8). */
    @JvmStatic
    fun sequence(bytes: ByteArray): Int {
        if (bytes.size < HEADER) throw IllegalArgumentException("batch truncated")
        return readIntLE(bytes, 8)
    }

    /** Encode a `META::RESYNC` request batch (host → guest). */
    @JvmStatic
    fun encodeResync(): ByteArray = singleMeta(Commands.Meta.RESYNC)

    /** Encode a `META::PONG` reply batch (host → guest). */
    @JvmStatic
    fun encodePong(): ByteArray = singleMeta(Commands.Meta.PONG)

    /** Encode a `META::PING` heartbeat probe batch (guest → host). */
    @JvmStatic
    fun encodePing(): ByteArray {
        val out = ByteArrayOutputStream()
        writeHeader(out, GUEST_TO_HOST, 0, 1)
        writeBytes(out, Opcode(Categories.META, Commands.Meta.PING, 0, 0, 0, 0).toBytes())
        writeIntLE(out, 0)
        return out.toByteArray()
    }

    private fun singleMeta(command: Int): ByteArray {
        val out = ByteArrayOutputStream()
        writeHeader(out, HOST_TO_GUEST, 0, 1)
        writeBytes(out, Opcode(Categories.META, command, 0, 0, 0, 0).toBytes())
        writeIntLE(out, 0)
        return out.toByteArray()
    }

    /** Encode a `META::ENVIRONMENT` field batch (viewport + route). */
    @JvmStatic
    fun encodeEnvironment(env: EnvironmentData): ByteArray {
        val route = env.route.toByteArray(StandardCharsets.UTF_8)
        val ops = ArrayList<Opcode>(3)
        if (env.viewportWidth > 0) {
            ops.add(Opcode(Categories.META, Commands.Meta.ENVIRONMENT, 0,
                Commands.Environment.VIEWPORT_WIDTH, env.viewportWidth.toRawBits(), 0))
        }
        if (env.viewportHeight > 0) {
            ops.add(Opcode(Categories.META, Commands.Meta.ENVIRONMENT, 0,
                Commands.Environment.VIEWPORT_HEIGHT, env.viewportHeight.toRawBits(), 0))
        }
        ops.add(Opcode(Categories.META, Commands.Meta.ENVIRONMENT, 0,
            Commands.Environment.ROUTE, 0, 0))
        val out = ByteArrayOutputStream()
        writeHeader(out, HOST_TO_GUEST, 0, ops.size)
        for (op in ops) {
            writeBytes(out, op.toBytes())
        }
        writeIntLE(out, 4 + route.size)
        writeIntLE(out, route.size)
        out.writeBytes(route)
        return out.toByteArray()
    }

    /** True when the batch is a `META::RESYNC` request. */
    @JvmStatic
    fun isResync(bytes: ByteArray): Boolean =
        parse(bytes).opcodes.any { it.category == Categories.META && it.command == Commands.Meta.RESYNC }

    /** True when the batch carries a `META::PING` heartbeat probe. */
    @JvmStatic
    fun isPing(bytes: ByteArray): Boolean =
        parse(bytes).opcodes.any { it.category == Categories.META && it.command == Commands.Meta.PING }

    /** True when the batch carries `META::ENVIRONMENT` fields. */
    @JvmStatic
    fun isEnvironment(bytes: ByteArray): Boolean =
        parse(bytes).opcodes.any { it.category == Categories.META && it.command == Commands.Meta.ENVIRONMENT }

    /** Decode a `META::ENVIRONMENT` field batch into [EnvironmentData]. */
    @JvmStatic
    fun decodeEnvironment(bytes: ByteArray): EnvironmentData {
        val parsed = parse(bytes)
        var route: String? = null
        var width = -1f
        var height = -1f
        for (op in parsed.opcodes) {
            if (op.category != Categories.META || op.command != Commands.Meta.ENVIRONMENT) continue
            when (op.a and 0xFFFF) {
                Commands.Environment.VIEWPORT_WIDTH -> width = Float.fromBits(op.b)
                Commands.Environment.VIEWPORT_HEIGHT -> height = Float.fromBits(op.b)
                Commands.Environment.ROUTE -> route = parsed.stringAt(op.b)
            }
        }
        return EnvironmentData(route, width, height)
    }

    /** Encode host → guest events as a batch. */
    @JvmStatic
    fun encodeEvents(events: List<Event>): ByteArray {
        val opcodes = ArrayList<Opcode>(events.size)
        val strings = ByteArrayOutputStream()
        for (event in events) {
            when {
                event.isTextChanged -> {
                    val offset = strings.size()
                    val utf8 = event.text.orEmpty().toByteArray(StandardCharsets.UTF_8)
                    writeIntLE(strings, utf8.size)
                    strings.writeBytes(utf8)
                    opcodes.add(Opcode(
                        Categories.EVENT, Commands.Event.TEXT_CHANGED, 0, event.target, offset, 0))
                }
                event.isNavigate -> {
                    if (event.isNavigateBack) {
                        opcodes.add(Opcode(Categories.EVENT, Commands.Event.NAVIGATE, 0, 0, 0, 0))
                    } else {
                        val offset = strings.size()
                        val utf8 = event.url().orEmpty().toByteArray(StandardCharsets.UTF_8)
                        writeIntLE(strings, utf8.size)
                        strings.writeBytes(utf8)
                        opcodes.add(Opcode(
                            Categories.EVENT, Commands.Event.NAVIGATE, Commands.Flags.NAVIGATE_URL, 0, offset, 0))
                    }
                }
                event.isValueChanged -> opcodes.add(Opcode(
                    Categories.EVENT, Commands.Event.VALUE_CHANGED, 0,
                    event.target, event.value.toRawBits(), 0))
                event.isKeyDown || event.isKeyUp -> opcodes.add(Opcode(
                    Categories.EVENT, event.command, event.flags, event.target, event.b, event.c))
                event.isDateChanged -> opcodes.add(Opcode(
                    Categories.EVENT, Commands.Event.DATE_CHANGED, 0, event.target, event.b, event.c))
                event.isFocusChanged || event.isEditingChanged || event.isSubmit -> opcodes.add(Opcode(
                    Categories.EVENT, event.command, 0, event.target, event.b, 0))
                event.isMediaTimeUpdated || event.isMediaVolumeChanged ||
                    event.isMediaDurationChanged || event.isFitChanged -> opcodes.add(Opcode(
                    Categories.EVENT, event.command, 0, event.target, event.value.toRawBits(), 0))
                event.isMediaPlayStateChanged || event.isMediaEnded -> opcodes.add(Opcode(
                    Categories.EVENT, event.command, 0, event.target, event.b, 0))
                else -> opcodes.add(Opcode(
                    Categories.EVENT, event.command, event.flags, event.target,
                    event.x.toRawBits(), event.y.toRawBits()))
            }
        }
        val out = ByteArrayOutputStream()
        writeHeader(out, HOST_TO_GUEST, 0, opcodes.size)
        for (op in opcodes) {
            writeBytes(out, op.toBytes())
        }
        writeIntLE(out, strings.size())
        writeBytes(out, strings.toByteArray())
        return out.toByteArray()
    }

    /** Decode a host → guest event batch into typed events. */
    @JvmStatic
    fun decodeEvents(bytes: ByteArray): List<Event> {
        val parsed = parse(bytes)
        val events = ArrayList<Event>()
        for (op in parsed.opcodes) {
            if (op.category != Categories.EVENT) continue
            when (op.command) {
                Commands.Event.TEXT_CHANGED -> events.add(Event.textChanged(op.a, parsed.stringAt(op.b)))
                Commands.Event.NAVIGATE -> events.add(
                    if ((op.flags and Commands.Flags.NAVIGATE_URL) != 0) {
                        Event.navigate(parsed.stringAt(op.b))
                    } else {
                        Event.navigateBack()
                    })
                Commands.Event.VALUE_CHANGED -> events.add(Event.valueChanged(op.a, Float.fromBits(op.b)))
                Commands.Event.KEY_DOWN -> events.add(Event.keyDown(op.a, op.b, op.c, op.flags))
                Commands.Event.KEY_UP -> events.add(Event.keyUp(op.a, op.b, op.c))
                Commands.Event.DATE_CHANGED -> events.add(Event.dateChanged(op.a, op.b, op.c))
                Commands.Event.FOCUS_CHANGED -> events.add(Event.focusChanged(op.a, op.b != 0))
                Commands.Event.EDITING_CHANGED -> events.add(Event.editingChanged(op.a, op.b != 0))
                Commands.Event.SUBMIT -> events.add(Event.submit(op.a))
                Commands.Event.SCROLL -> events.add(Event.scroll(
                    op.a, Float.fromBits(op.b), Float.fromBits(op.c)))
                Commands.Event.WHEEL -> events.add(Event.wheel(
                    op.a, Float.fromBits(op.b), Float.fromBits(op.c)))
                Commands.Event.MEDIA_PLAY_STATE_CHANGED -> events.add(
                    Event.mediaPlayStateChanged(op.a, op.b != 0))
                Commands.Event.MEDIA_TIME_UPDATED -> events.add(
                    Event.mediaTimeUpdated(op.a, Float.fromBits(op.b)))
                Commands.Event.MEDIA_ENDED -> events.add(Event.mediaEnded(op.a))
                Commands.Event.MEDIA_VOLUME_CHANGED -> events.add(
                    Event.mediaVolumeChanged(op.a, Float.fromBits(op.b)))
                Commands.Event.MEDIA_DURATION_CHANGED -> events.add(
                    Event.mediaDurationChanged(op.a, Float.fromBits(op.b)))
                Commands.Event.FIT_CHANGED -> events.add(
                    Event.fitChanged(op.a, Float.fromBits(op.b)))
                Commands.Event.POINTER_DOWN, Commands.Event.POINTER_MOVE, Commands.Event.POINTER_UP ->
                    events.add(Event(op.command, op.a, op.flags, Float.fromBits(op.b),
                        Float.fromBits(op.c), 0f, null, 0, 0))
            }
        }
        return events
    }

    private class Parsed(val opcodes: List<Opcode>, val strings: ByteArray) {
        fun stringAt(offset: Int): String {
            val len = (strings[offset].toInt() and 0xFF) or
                ((strings[offset + 1].toInt() and 0xFF) shl 8) or
                ((strings[offset + 2].toInt() and 0xFF) shl 16) or
                ((strings[offset + 3].toInt() and 0xFF) shl 24)
            return String(strings, offset + 4, len, StandardCharsets.UTF_8)
        }
    }

    private fun parse(bytes: ByteArray): Parsed {
        if (bytes.size < HEADER) throw IllegalArgumentException("batch truncated")
        val magic = readIntLE(bytes, 0)
        if (magic != MAGIC) {
            throw IllegalArgumentException("bad batch magic 0x${Integer.toHexString(magic)}")
        }
        val version = (bytes[4].toInt() and 0xFF) or ((bytes[5].toInt() and 0xFF) shl 8)
        if (version != VERSION) {
            throw IllegalArgumentException("unsupported batch version $version")
        }
        val opcodeCount = readIntLE(bytes, 12)
        val opcodesEnd = HEADER + opcodeCount * Opcode.SIZE
        if (opcodesEnd + 4 > bytes.size) {
            throw IllegalArgumentException("batch truncated (opcodes)")
        }
        val opcodes = ArrayList<Opcode>(opcodeCount)
        for (i in 0 until opcodeCount) {
            val slot = ByteArray(Opcode.SIZE)
            System.arraycopy(bytes, HEADER + i * Opcode.SIZE, slot, 0, Opcode.SIZE)
            opcodes.add(Opcode.fromBytes(slot))
        }
        val stringsLen = readIntLE(bytes, opcodesEnd)
        val stringsStart = opcodesEnd + 4
        if (stringsStart + stringsLen > bytes.size) {
            throw IllegalArgumentException("batch truncated (strings)")
        }
        val strings = ByteArray(stringsLen)
        System.arraycopy(bytes, stringsStart, strings, 0, stringsLen)
        return Parsed(opcodes, strings)
    }

    private fun writeHeader(out: ByteArrayOutputStream, flags: Int, sequence: Int, opcodeCount: Int) {
        writeIntLE(out, MAGIC)
        writeShortLE(out, VERSION)
        writeShortLE(out, flags)
        writeIntLE(out, sequence)
        writeIntLE(out, opcodeCount)
    }

    private fun writeIntLE(out: ByteArrayOutputStream, value: Int) {
        out.write(value and 0xFF)
        out.write((value ushr 8) and 0xFF)
        out.write((value ushr 16) and 0xFF)
        out.write((value ushr 24) and 0xFF)
    }

    private fun writeShortLE(out: ByteArrayOutputStream, value: Int) {
        out.write(value and 0xFF)
        out.write((value ushr 8) and 0xFF)
    }

    private fun writeBytes(out: ByteArrayOutputStream, bytes: ByteArray) {
        out.writeBytes(bytes)
    }

    private fun readIntLE(bytes: ByteArray, offset: Int): Int =
        (bytes[offset].toInt() and 0xFF) or
            ((bytes[offset + 1].toInt() and 0xFF) shl 8) or
            ((bytes[offset + 2].toInt() and 0xFF) shl 16) or
            ((bytes[offset + 3].toInt() and 0xFF) shl 24)
}

