        ("LIST", value_type::LIST),
    ] {
        row(&mut out, "value_type", "", name, &hex_u8(value));
    }
    out.push('\n');

    for (name, value) in properties() {
        row(&mut out, "property", "", name, &hex_u16(value));
    }
    out.push('\n');

    for (name, value) in properties() {
        row(
            &mut out,
            "property_value_type",
            "",
            name,
            value_type_name(value_type_for(value)),
        );
    }

